_SSE_DONE = object()


class _ConnectionRecorder:
    """Keeps track of the live HTTP connections so they can be aborted."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._connections: list[Any] = []

    def add(self, connection: Any) -> None:
        with self._lock:
            self._connections.append(connection)

    def discard(self, connection: Any) -> None:
        with self._lock:
            try:
                self._connections.remove(connection)
            except ValueError:
                pass

    def abort(self) -> None:
        with self._lock:
            connections = list(self._connections)
            self._connections.clear()
        for connection in connections:
            try:
                sock = getattr(connection, "sock", None)
                if sock is not None:
                    sock.shutdown(socket.SHUT_RDWR)
            except Exception:
                pass
            try:
                connection.close()
            except Exception:
                pass


class _RecordingHTTPHandler(urllib.request.HTTPHandler):
    """HTTP handler that registers connections with a recorder."""

    recorder: _ConnectionRecorder | None = None

    def http_open(self, req: Any) -> Any:
        connection = self.do_open(http.client.HTTPConnection, req)
        if self.recorder is not None:
            self.recorder.add(connection)
        return connection


class _RecordingHTTPSHandler(urllib.request.HTTPSHandler):
    """HTTPS handler that registers connections with a recorder."""

    recorder: _ConnectionRecorder | None = None

    def https_open(self, req: Any) -> Any:
        connection = self.do_open(http.client.HTTPSConnection, req)
        if self.recorder is not None:
            self.recorder.add(connection)
        return connection


def _response_socket(response: Any) -> Any:
    """Find the live socket behind an ``http.client`` response.

    The socket is reached through several layers of ``http.client`` internals
    that differ between Python versions and platforms, so every known handle
    is tried before giving up.
    """
    for getter in (
        lambda: getattr(getattr(response, "fp", None), "raw", None),
        lambda: getattr(response, "raw", None),
        lambda: response,
    ):
        try:
            candidate = getter()
        except Exception:
            candidate = None
        if candidate is None:
            continue
        for attribute in ("_sock", "sock"):
            try:
                found = getattr(candidate, attribute, None)
            except Exception:
                found = None
            if found is not None:
                return found
    return None


def _abort_response(response: Any) -> None:
    """Shut down the socket so a blocked read in another thread returns.

    Shutting the socket down is what actually unblocks a reader; ``close()``
    alone can leave the read hanging until the request timeout.

    ``response.close()`` is deliberately not called here: ``http.client``
    waits for the underlying socket to drain, which blocks for as long as the
    peer keeps the connection open. The socket shutdown is enough to release
    the reader, and the caller closes the response afterwards.
    """
    sock = _response_socket(response)
    if sock is not None:
        try:
            sock.shutdown(socket.SHUT_RDWR)
        except Exception:
            pass
        try:
            sock.close()
        except Exception:
            pass


def _arguments_complete(value: str) -> bool:
    """Whether a tool-argument string is a complete, well-formed JSON object.

    Used to tell a gateway resending the whole payload apart from a genuine
    stream fragment that merely happens to start with '{' (for example the
    content of a file whose first byte is a brace).
    """
    text = (value or "").strip()
    if not text.startswith("{") or not text.endswith("}"):
        return False
    try:
        parsed = json.loads(text)
    except (json.JSONDecodeError, TypeError, ValueError):
        return False
    return isinstance(parsed, dict)


def _merge_tool_arguments(existing: str, fragment: str) -> str:
    """Merge streamed tool arguments, tolerating gateways that resend JSON.

    Some gateways resend the entire argument payload instead of the next
    fragment. Detect that by checking whether the fragment alone parses as a
    complete JSON object *and* covers everything accumulated so far; anything
    else is treated as a real continuation and appended, so string values that
    begin with '{' are never mistaken for a resent payload.
    """
    if not fragment:
        return existing
    if not existing or fragment == existing:
        return fragment
    if _arguments_complete(fragment) and len(fragment) >= len(existing):
        accumulated = (existing + fragment).strip()
        if accumulated != fragment.strip() and not _arguments_complete(accumulated):
            return fragment
        if accumulated == fragment.strip():
            return fragment
    return existing + fragment


class BaseChatClient:
    def __init__(
        self,
        base_url: str,
        api_key: str,
        model: str,
        timeout: float = 120.0,
        max_retries: int = 3,
        temperature: float | None = None,
        reasoning: ReasoningConfig | None = None,
        max_tokens: int | None = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key
        self.model = model
        self.timeout = timeout
        self.max_retries = max_retries
        self.temperature = temperature
        self.reasoning = reasoning
        self.max_tokens = max_tokens
        self.supports_reasoning_config = True
        self.last_usage: dict[str, Any] = {}
        self.last_finish_reason: str | None = None
        self.last_turn_usage: dict[str, int] = {}
        self.last_turn_truncated = False
        self.last_reasoning_ignored = False
        self.last_models_payload: Any = None
        # 上次模型调用时的真实 prompt token 数及其本地估算基线，
        # 用于在两次调用之间推算当前上下文占用（比纯估算准）。
        self.last_prompt_tokens: int | None = None
        self.last_prompt_estimate: int | None = None
        # Streaming is negotiated per client: some gateways reject stream=true
        # or stream_options; remember that for the rest of the process.
        self.supports_stream = True
        self.supports_stream_options = True
        self.supports_cancel = True
        self.stream_idle_timeout = 300.0
        self.debug_stream = False

    def _headers(self) -> dict[str, str]:
        headers = {"Accept": "application/json"}
        if self.api_key:
            headers["Authorization"] = f"Bearer {self.api_key}"
        return headers

    def _v1_root(self) -> str:
        return self.base_url if self.base_url.endswith("/v1") else f"{self.base_url}/v1"

    def _request(
        self,
        url: str,
        payload: dict[str, Any] | None = None,
        timeout: float | None = None,
        cancel_event: "threading.Event | None" = None,
    ) -> dict[str, Any]:
        headers = self._headers()
        data = None
        if payload is not None:
            data = json.dumps(payload).encode("utf-8")
            headers["Content-Type"] = "application/json"
        request = urllib.request.Request(
            url, data=data, headers=headers, method="POST" if data is not None else "GET"
        )

        for attempt in range(self.max_retries + 1):
            if cancel_event is not None and cancel_event.is_set():
                raise ChatCancelled()
            retry_after = None
            try:
                response = self._open_with_cancel(request, timeout, cancel_event)
                raw = self._read_response(response, cancel_event).decode(
                    "utf-8", "replace"
                )
                try:
                    return json.loads(raw)
                except json.JSONDecodeError as exc:
                    raise ChatError(f"API returned invalid JSON: {raw[:500]}") from exc
            except ChatCancelled:
                raise
            except urllib.error.HTTPError as exc:
                detail = exc.read().decode("utf-8", "replace")[:1000]
                retry_after = exc.headers.get("Retry-After")
                error = ChatError(f"HTTP {exc.code} from {url}: {detail}")
                if exc.code not in (408, 409, 429) and exc.code < 500:
                    raise error from exc
            except (urllib.error.URLError, TimeoutError, OSError, ValueError, HTTPException) as exc:
                if cancel_event is not None and cancel_event.is_set():
                    raise ChatCancelled() from exc
                error = ChatError(f"Cannot reach {url}: {getattr(exc, 'reason', exc)}")

            if attempt == self.max_retries:
                raise error
            delay = _retry_delay(retry_after, attempt)
            print(f"[retry] {error}; retrying in {delay:.1f}s", file=sys.stderr)
            time.sleep(delay)

    def _open_with_cancel(
        self,
        request: Any,
        timeout: float | None,
        cancel_event: "threading.Event | None",
    ) -> Any:
        """Open a connection that stays responsive to a cancel request.

        ``urlopen`` blocks until the response headers arrive and keeps the
        socket hidden while it waits, so a cancel request would otherwise be
        ignored until the server answers or the timeout expires. Running the
        request on a worker thread lets the caller notice the cancel; the
        worker keeps every urllib behaviour (redirects, proxies, error
        mapping) intact.
        """
        limit = timeout or self.timeout
        if cancel_event is None:
            return urllib.request.urlopen(request, timeout=limit)

        recorder = _ConnectionRecorder()
        http_handler = _RecordingHTTPHandler()
        http_handler.recorder = recorder
        https_handler = _RecordingHTTPSHandler()
        https_handler.recorder = recorder
        opener = urllib.request.build_opener(http_handler, https_handler)
        box: dict[str, Any] = {}
        done = threading.Event()

        def worker() -> None:
            try:
                box["response"] = opener.open(request, timeout=limit)
            except BaseException as exc:  # noqa: BLE001  forwarded to the caller
                box["error"] = exc
            finally:
                done.set()

        thread = threading.Thread(target=worker, daemon=True)
        thread.start()
        while not done.wait(0.1):
            if cancel_event.is_set():
                recorder.abort()
                done.wait(0.5)
                raise ChatCancelled()
        if "error" in box:
            raise box["error"]
        return box["response"]
    def _read_response(
        self,
        response: Any,
        cancel_event: "threading.Event | None" = None,
    ) -> bytes:
        stop = threading.Event()
        watcher: threading.Thread | None = None

        def watch() -> None:
            while not stop.wait(0.2):
                if cancel_event is not None and cancel_event.is_set():
                    _abort_response(response)
                    return

        if cancel_event is not None:
            watcher = threading.Thread(target=watch, daemon=True)
            watcher.start()
        try:
            return self._read_body(response, cancel_event)
        except (TimeoutError, OSError, ValueError, HTTPException) as exc:
            if cancel_event is not None and cancel_event.is_set():
                raise ChatCancelled() from exc
            raise
        finally:
            stop.set()
            if watcher is not None:
                watcher.join(timeout=0.5)
            if cancel_event is None or not cancel_event.is_set():
                # A cancelled response was already torn down by _abort_response;
                # closing it again would block on the still-open socket.
                try:
                    response.close()
                except Exception:
                    pass

    def _read_body(
        self,
        response: Any,
        cancel_event: "threading.Event | None" = None,
    ) -> bytes:
        """Read the whole body, staying responsive to a cancel request.

        Closing the socket does not reliably wake a reader that is already
        blocked inside ``recv`` on Windows, so the read runs on a worker
        thread while this thread watches the cancel flag. The socket is shut
        down on cancel to unblock the worker.
        """
        if cancel_event is None:
            return response.read()
        box: dict[str, Any] = {}
        done = threading.Event()

        def worker() -> None:
            try:
                box["body"] = response.read()
            except BaseException as exc:  # noqa: BLE001  forwarded to the caller
                box["error"] = exc
            finally:
                done.set()

        thread = threading.Thread(target=worker, daemon=True)
        thread.start()
        while not done.wait(0.1):
            if cancel_event.is_set():
                _abort_response(response)
                done.wait(0.5)
                raise ChatCancelled()
        if "error" in box:
            error = box["error"]
            if isinstance(error, (TimeoutError, OSError, ValueError, HTTPException)):
                raise error
            raise error
        return box.get("body") or b""

    def _models_root(self) -> str:
        return self.base_url

    def _stream_debug(self, text: str) -> None:
        if self.debug_stream:
            print(f"[stream] {text}", file=sys.stderr, flush=True)

    def _direct_json_response(self, response: Any) -> dict[str, Any] | None:
        """Some gateways ignore stream=true and return one JSON document."""
        content_type = ""
        headers = getattr(response, "headers", None)
        if headers is not None:
            content_type = (headers.get("Content-Type") or "").lower()
        if "text/event-stream" in content_type:
            return None
        if "application/json" not in content_type:
            return None
        try:
            raw = response.read()
        except (TimeoutError, OSError, HTTPException):
            return None
        try:
            data = json.loads(raw.decode("utf-8", "replace"))
        except (ValueError, AttributeError):
            return None
        return data if isinstance(data, dict) else None

    def _open_stream(
        self,
        url: str,
        payload: dict[str, Any],
        timeout: float | None = None,
    ) -> Any:
        """Open an SSE request, retrying connection/HTTP errors.

        A 4xx that looks like "this endpoint does not stream" raises
        StreamNotSupported so the caller can retry without streaming.
        """
        headers = self._headers()
        headers["Accept"] = "text/event-stream"
        headers["Content-Type"] = "application/json"
        data = json.dumps(payload).encode("utf-8")
        timeout_value = timeout or self.stream_idle_timeout
        for attempt in range(self.max_retries + 1):
            retry_after = None
            request = urllib.request.Request(
                url, data=data, headers=headers, method="POST"
            )
            try:
                return urllib.request.urlopen(request, timeout=timeout_value)
            except urllib.error.HTTPError as exc:
                detail = exc.read().decode("utf-8", "replace")[:1000]
                retry_after = exc.headers.get("Retry-After")
                if exc.code in (400, 404, 405, 422, 501):
                    raise StreamNotSupported(
                        f"HTTP {exc.code} from {url}: {detail}"
                    ) from exc
                error = ChatError(f"HTTP {exc.code} from {url}: {detail}")
                if exc.code not in (408, 409, 429) and exc.code < 500:
                    raise error from exc
            except (urllib.error.URLError, TimeoutError, OSError) as exc:
                error = ChatError(
                    f"Cannot reach {url}: {getattr(exc, 'reason', exc)}"
                )

            if attempt == self.max_retries:
                raise error
            delay = _retry_delay(retry_after, attempt)
            print(f"[retry] {error}; retrying in {delay:.1f}s", file=sys.stderr)
            time.sleep(delay)

    def _sse_events(
        self,
        line: str,
    ) -> list[Any]:
        line = line.rstrip("\r")
        if not line or line.startswith(":") or not line.startswith("data:"):
            return []
        data = line[len("data:"):].strip()
        if not data:
            return []
        if data == "[DONE]":
            return [_SSE_DONE]
        try:
            event = json.loads(data)
        except json.JSONDecodeError:
            self._stream_debug("bad-json")
            return []
        if not isinstance(event, dict):
            return []
        self._stream_debug(str(event.get("type") or "data"))
        return [event]

    def _iter_sse(
        self,
        response: Any,
        cancel_event: "threading.Event | None" = None,
    ) -> Any:
        decoder = codecs.getincrementaldecoder("utf-8")("replace")
        stop = threading.Event()
        watcher: threading.Thread | None = None

        def watch() -> None:
            while not stop.wait(0.2):
                if cancel_event is not None and cancel_event.is_set():
                    _abort_response(response)
                    return

        if cancel_event is not None:
            watcher = threading.Thread(target=watch, daemon=True)
            watcher.start()
        try:
            while True:
                if cancel_event is not None and cancel_event.is_set():
                    raise ChatCancelled()
                try:
                    raw_line = response.readline()
                except (TimeoutError, OSError, ValueError, HTTPException) as exc:
                    if cancel_event is not None and cancel_event.is_set():
                        raise ChatCancelled() from exc
                    raise ChatError(f"stream read failed: {exc}") from exc
                if not raw_line:
                    break
                line = decoder.decode(raw_line)
                for event in self._sse_events(line):
                    yield event
        finally:
            stop.set()
            if watcher is not None:
                watcher.join(timeout=0.5)
            try:
                response.close()
            except Exception:
                pass

    def list_models(self) -> list[str]:
        url = f"{self._models_root()}/models"
        timeout = min(self.timeout, 30.0)
        payload = self._request(url, timeout=timeout)
        pages: list[Any] = [payload]
        visited = {url}
        next_url = model_page_url(url, payload)
        while (
            next_url
            and next_url not in visited
            and len(pages) < MODEL_LIST_MAX_PAGES
        ):
            visited.add(next_url)
            page = self._request(next_url, timeout=timeout)
            pages.append(page)
            next_url = model_page_url(next_url, page)
        if len(pages) > 1:
            items: list[Any] = []
            for page in pages:
                items.extend(model_list_items(page) or [])
            payload = {"object": "list", "data": items}
        self.last_models_payload = payload
        models = extract_model_ids(payload)[:MODEL_LIST_MAX_ITEMS]
        if models:
            return models
        if isinstance(payload, list):
            return []
        if isinstance(payload, dict) and any(
            key in payload for key in ("data", "models", "model_list", "items")
        ):
            return []
        raise ChatError(f"Unexpected models response: {json.dumps(payload)[:500]}")


class ChatClient(BaseChatClient):
    def _build_payload(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "model": self.model,
            # Underscore keys are local-only (e.g. _thinking) and must not reach the API.
            "messages": [
                {key: value for key, value in message.items() if not key.startswith("_")}
                for message in messages
            ],
        }
        if self.temperature is not None:
            payload["temperature"] = self.temperature
        if self.max_tokens is not None:
            payload["max_tokens"] = self.max_tokens
        if self.reasoning is not None:
            payload.update(reasoning_payload(self.reasoning))
        if tools:
            payload["tools"] = tools
            payload["tool_choice"] = "auto"
        return payload

    def _finalize(self, data: dict[str, Any]) -> dict[str, Any]:
        try:
            choice = data["choices"][0]
            message = choice["message"]
        except (KeyError, IndexError, TypeError) as exc:
            raise ChatError(f"Unexpected API response: {json.dumps(data)[:1000]}") from exc
        if not isinstance(message, dict):
            raise ChatError(f"Unexpected API response: {json.dumps(data)[:1000]}")
        content = message.get("content")
        if isinstance(content, list):
            message["content"] = _plain_text(content)
        elif content is None:
            message["content"] = ""
        usage = data.get("usage")
        self.last_usage = usage if isinstance(usage, dict) else {}
        finish_reason = choice.get("finish_reason") if isinstance(choice, dict) else None
        self.last_finish_reason = finish_reason if isinstance(finish_reason, str) else None
        if self.reasoning is not None and self.reasoning.level == "off":
            details = self.last_usage.get("completion_tokens_details")
            reasoning_tokens = details.get("reasoning_tokens") if isinstance(details, dict) else 0
            reasoning_text = message.get("reasoning_content") or message.get("reasoning") or ""
            if (isinstance(reasoning_tokens, int) and reasoning_tokens > 0) or (
                isinstance(reasoning_text, str) and reasoning_text.strip()
            ):
                self.last_reasoning_ignored = True
        return message

    def _chat_once(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        cancel_event: "threading.Event | None" = None,
    ) -> dict[str, Any]:
        self.last_reasoning_ignored = False
        payload = self._build_payload(messages, tools)
        data = self._request(
            f"{self.base_url}/chat/completions",
            payload,
            cancel_event=cancel_event,
        )
        return self._finalize(data)

    def _stream_chat(
        self,
        payload: dict[str, Any],
        on_delta: Callable[[str, str], None],
        cancel_event: "threading.Event | None",
    ) -> dict[str, Any]:
        self.last_reasoning_ignored = False
        content_parts: list[str] = []
        reasoning_parts: list[str] = []
        tool_slots: dict[int, dict[str, Any]] = {}
        finish_reason: str | None = None
        usage: dict[str, Any] = {}
        saw_event = False
        saw_done = False

        response = self._open_stream(
            f"{self.base_url}/chat/completions", payload
        )
        direct = self._direct_json_response(response)
        if direct is not None:
            self._stream_debug("direct-json")
            return self._finalize(direct)
        for event in self._iter_sse(response, cancel_event):
            if event is _SSE_DONE:
                saw_done = True
                break
            saw_event = True
            error = event.get("error")
            if isinstance(error, dict):
                raise ChatError(
                    f"stream error: {error.get('message') or json.dumps(error)[:500]}"
                )
            choices = event.get("choices")
            if isinstance(choices, list) and choices:
                choice = choices[0]
                if not isinstance(choice, dict):
                    continue
                delta = choice.get("delta")
                if isinstance(delta, dict):
                    text = delta.get("content")
                    if isinstance(text, list):
                        text = _plain_text(text)
                    if isinstance(text, str) and text:
                        content_parts.append(text)
                        self._stream_debug(f"content len={len(text)}")
                        on_delta("content", text)
                    reasoning = (
                        delta.get("reasoning_content")
                        or delta.get("reasoning")
                    )
                    if isinstance(reasoning, str) and reasoning:
                        reasoning_parts.append(reasoning)
                        on_delta("thinking", reasoning)
                    for index, raw_call in enumerate(delta.get("tool_calls") or []):
                        if not isinstance(raw_call, dict):
                            continue
                        slot_index = raw_call.get("index")
                        if not isinstance(slot_index, int):
                            slot_index = index
                        slot = tool_slots.setdefault(
                            slot_index,
                            {"id": "", "name": "", "arguments": ""},
                        )
                        call_id = raw_call.get("id")
                        if isinstance(call_id, str) and call_id:
                            slot["id"] = call_id
                        function = raw_call.get("function")
                        if isinstance(function, dict):
                            name = function.get("name")
                            if isinstance(name, str) and name and not slot["name"]:
                                slot["name"] = name
                            fragment = function.get("arguments")
                            if isinstance(fragment, str) and fragment:
                                slot["arguments"] = _merge_tool_arguments(
                                    slot["arguments"], fragment
                                )
                reason = choice.get("finish_reason")
                if isinstance(reason, str):
                    finish_reason = reason
            event_usage = event.get("usage")
            if isinstance(event_usage, dict) and event_usage:
                usage = event_usage

        if not saw_event and not content_parts and not tool_slots:
            raise ChatError("stream ended without any response data")
        if (
            (content_parts or reasoning_parts or tool_slots)
            and finish_reason is None
            and not saw_done
        ):
            raise ChatError("stream ended before finish_reason")

        message: dict[str, Any] = {
            "role": "assistant",
            "content": "".join(content_parts),
        }
        if reasoning_parts:
            message["reasoning_content"] = "".join(reasoning_parts)
        if tool_slots:
            message["tool_calls"] = [
                {
                    "id": slot["id"] or f"call_{index}",
                    "type": "function",
                    "function": {
                        "name": slot["name"] or "unknown",
                        "arguments": slot["arguments"] or "{}",
                    },
                }
                for index, slot in sorted(tool_slots.items())
            ]
        data = {
            "choices": [{"message": message, "finish_reason": finish_reason}],
            "usage": usage,
        }
        return self._finalize(data)

    def chat(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        on_delta: Callable[[str, str], None] | None = None,
        cancel_event: "threading.Event | None" = None,
    ) -> dict[str, Any]:
        if on_delta is None or not self.supports_stream:
            return self._chat_once(messages, tools, cancel_event)
        payload = self._build_payload(messages, tools)
        payload["stream"] = True
        if self.supports_stream_options:
            payload["stream_options"] = {"include_usage": True}
        while True:
            try:
                return self._stream_chat(payload, on_delta, cancel_event)
            except StreamNotSupported:
                if payload.pop("stream_options", None) is not None:
                    self.supports_stream_options = False
                    self._stream_debug("retry without stream_options")
                    continue
                self.supports_stream = False
                self._stream_debug("fallback to non-streaming")
                return self._chat_once(messages, tools, cancel_event)


# --------------------------------------------------------------------------- #
# Anthropic Messages protocol
# --------------------------------------------------------------------------- #

ANTHROPIC_IMAGE_TYPES = {"image/jpeg", "image/png", "image/gif", "image/webp"}
ANTHROPIC_STOP_REASONS = {
    "end_turn": "stop",
    "stop_sequence": "stop",
    "tool_use": "tool_calls",
    "max_tokens": "length",
    "pause_turn": "stop",
    "refusal": "stop",
}


def _plain_text(content: Any) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "\n".join(
            part.get("text") or ""
            for part in content
            if isinstance(part, dict) and part.get("type") == "text"
        )
    return ""


def _anthropic_image_block(url: str) -> dict[str, Any]:
    if url.startswith(("http://", "https://")):
        return {"type": "image", "source": {"type": "url", "url": url}}
    prefix, separator, payload = url.partition(",")
    if not separator or not prefix.startswith("data:image/") or not prefix.endswith(";base64"):
        raise ImageError("unsupported image URL for the Anthropic protocol")
    media_type = prefix[len("data:"):-len(";base64")]
    if media_type not in ANTHROPIC_IMAGE_TYPES:
        raise ImageError(f"Anthropic does not support {media_type}; use PNG, JPEG, GIF or WEBP")
    return {
        "type": "image",
        "source": {"type": "base64", "media_type": media_type, "data": payload},
    }


def _anthropic_user_blocks(content: Any) -> list[dict[str, Any]]:
    if isinstance(content, str):
        return [{"type": "text", "text": content}] if content else []
    if not isinstance(content, list):
        return []
    blocks: list[dict[str, Any]] = []
    for part in content:
        if not isinstance(part, dict):
            continue
        if part.get("type") == "text":
            text = part.get("text") or ""
            if text:
                blocks.append({"type": "text", "text": text})
        elif part.get("type") == "image_url":
            url = (part.get("image_url") or {}).get("url")
            if isinstance(url, str) and url:
                blocks.append(_anthropic_image_block(url))
    return blocks


def _anthropic_assistant_blocks(message: dict[str, Any]) -> list[dict[str, Any]]:
    blocks: list[dict[str, Any]] = []
    thinking_blocks = message.get("_thinking_blocks")
    if isinstance(thinking_blocks, list):
        for block in thinking_blocks:
            if isinstance(block, dict) and block.get("type") in ("thinking", "redacted_thinking"):
                blocks.append(block)
    content = message.get("content")
    if isinstance(content, str):
        if content:
            blocks.append({"type": "text", "text": content})
    elif isinstance(content, list):
        for part in content:
            if isinstance(part, dict) and part.get("type") == "text":
                text = part.get("text") or ""
                if text:
                    blocks.append({"type": "text", "text": text})
    for index, call in enumerate(message.get("tool_calls") or []):
        function = call.get("function") or {}
        raw = function.get("arguments") or "{}"
        try:
            arguments = json.loads(raw)
        except (json.JSONDecodeError, TypeError):
            arguments = {}
        if not isinstance(arguments, dict):
            arguments = {}
        blocks.append({
            "type": "tool_use",
            "id": call.get("id") or f"call_{index}",
            "name": function.get("name") or "unknown",
            "input": arguments,
        })
    return blocks


def _anthropic_tool_result(message: dict[str, Any]) -> dict[str, Any]:
    content = message.get("content")
    if isinstance(content, list):
        text = _plain_text(content)
    elif isinstance(content, str):
        text = content
    else:
        text = json.dumps(content, ensure_ascii=False)
    result: dict[str, Any] = {
        "type": "tool_result",
        "tool_use_id": message.get("tool_call_id") or "",
        "content": text,
    }
    if text.startswith("error:"):
        result["is_error"] = True
    return result


def _append_anthropic_message(converted: list[dict[str, Any]], role: str, blocks: list[dict[str, Any]]) -> None:
    if not blocks:
        return
    if converted and converted[-1]["role"] == role:
        converted[-1]["content"].extend(blocks)
    else:
        converted.append({"role": role, "content": blocks})


def _to_anthropic_messages(messages: list[dict[str, Any]]) -> tuple[str, list[dict[str, Any]]]:
    system_parts: list[str] = []
    converted: list[dict[str, Any]] = []
    for message in messages:
        role = message.get("role")
        if role == "system":
            text = _plain_text(message.get("content"))
            if text:
                system_parts.append(text)
            continue
        if role == "user":
            _append_anthropic_message(converted, "user", _anthropic_user_blocks(message.get("content")))
            continue
        if role == "assistant":
            _append_anthropic_message(converted, "assistant", _anthropic_assistant_blocks(message))
            continue
        if role == "tool":
            _append_anthropic_message(converted, "user", [_anthropic_tool_result(message)])
    return "\n\n".join(system_parts), converted


def _anthropic_tools(tools: list[dict[str, Any]]) -> list[dict[str, Any]]:
    converted: list[dict[str, Any]] = []
    for tool in tools:
        function = tool.get("function") or {}
        converted.append({
            "name": function.get("name") or "unknown",
            "description": function.get("description") or "",
            "input_schema": function.get("parameters") or {"type": "object", "properties": {}},
        })
    return converted


def _anthropic_response(data: dict[str, Any]) -> tuple[dict[str, Any], str | None, dict[str, Any]]:
    content = data.get("content")
    if isinstance(content, str):
        content = [{"type": "text", "text": content}]
    if not isinstance(content, list):
        raise ChatError(f"Unexpected Anthropic response: {json.dumps(data)[:1000]}")
    texts: list[str] = []
    thinking_texts: list[str] = []
    thinking_blocks: list[dict[str, Any]] = []
    tool_calls: list[dict[str, Any]] = []
    for block in content:
        if not isinstance(block, dict):
            continue
        block_type = block.get("type")
        if block_type == "text":
            texts.append(block.get("text") or "")
        elif block_type == "thinking":
            thinking = block.get("thinking") or ""
            if thinking:
                thinking_texts.append(thinking)
            thinking_blocks.append(block)
        elif block_type == "redacted_thinking":
            thinking_blocks.append(block)
        elif block_type == "tool_use":
            tool_calls.append({
                "id": block.get("id") or f"call_{len(tool_calls)}",
                "type": "function",
                "function": {
                    "name": block.get("name") or "unknown",
                    "arguments": json.dumps(block.get("input") or {}, ensure_ascii=False),
                },
            })
    message: dict[str, Any] = {"role": "assistant", "content": "\n".join(texts)}
    if tool_calls:
        message["tool_calls"] = tool_calls
    if thinking_texts:
        message["reasoning_content"] = "\n".join(thinking_texts)
    if thinking_blocks:
        message["_thinking_blocks"] = thinking_blocks
    stop_reason = data.get("stop_reason")
    usage = data.get("usage") if isinstance(data.get("usage"), dict) else {}
    return message, stop_reason if isinstance(stop_reason, str) else None, usage


class AnthropicClient(BaseChatClient):
    def __init__(
        self,
        base_url: str,
        api_key: str,
        model: str,
        timeout: float = 120.0,
        max_retries: int = 3,
        temperature: float | None = None,
        max_tokens: int | None = None,
        anthropic_version: str = "2023-06-01",
        anthropic_auth: str = "x-api-key",
        reasoning: ReasoningConfig | None = None,
    ) -> None:
        super().__init__(
            base_url,
            api_key,
            model,
            timeout,
            max_retries,
            temperature,
            reasoning=reasoning,
            max_tokens=max_tokens if max_tokens else 8192,
        )
        self.anthropic_version = anthropic_version
        self.anthropic_auth = anthropic_auth
        self.supports_reasoning_config = True

    def _root(self) -> str:
        return self._v1_root()

    def _models_root(self) -> str:
        return self._root()

    def _headers(self) -> dict[str, str]:
        headers = {
            "Accept": "application/json",
            "anthropic-version": self.anthropic_version,
        }
        if self.api_key:
            if self.anthropic_auth == "bearer":
                headers["Authorization"] = f"Bearer {self.api_key}"
            else:
                headers["x-api-key"] = self.api_key
        return headers

    def _build_payload(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
    ) -> dict[str, Any]:
        try:
            system, converted = _to_anthropic_messages(messages)
        except ImageError as exc:
            raise ChatError(str(exc)) from exc
        payload: dict[str, Any] = {
            "model": self.model,
            "max_tokens": self.max_tokens or 8192,
            "messages": converted,
        }
        if system:
            payload["system"] = system
        if self.temperature is not None:
            payload["temperature"] = self.temperature
        if tools:
            payload["tools"] = _anthropic_tools(tools)
            payload["tool_choice"] = {"type": "auto"}
        if (
            self.reasoning is not None
            and self.reasoning.provider == "anthropic"
            and self.reasoning.level != "off"
        ):
            budgets = {
                "minimal": 1024,
                "low": 2048,
                "medium": 4096,
                "high": 6144,
                "max": 7168,
            }
            max_tokens = self.max_tokens or 8192
            budget = min(budgets.get(self.reasoning.level, 4096), max_tokens - 1024)
            if budget >= 1024:
                payload["thinking"] = {"type": "enabled", "budget_tokens": budget}
        return payload

    def _finalize(self, data: dict[str, Any]) -> dict[str, Any]:
        message, stop_reason, usage = _anthropic_response(data)
        input_tokens = int(usage.get("input_tokens") or 0)
        cache_read = int(usage.get("cache_read_input_tokens") or 0)
        cache_creation = int(usage.get("cache_creation_input_tokens") or 0)
        completion_tokens = int(usage.get("output_tokens") or 0)
        prompt_tokens = input_tokens + cache_read + cache_creation
        self.last_usage = {
            "prompt_tokens": prompt_tokens,
            "completion_tokens": completion_tokens,
            "total_tokens": prompt_tokens + completion_tokens,
        }
        if cache_read > 0:
            self.last_usage["prompt_tokens_details"] = {"cached_tokens": cache_read}
        output_details = usage.get("output_tokens_details")
        thinking_tokens = (
            output_details.get("thinking_tokens") if isinstance(output_details, dict) else None
        )
        if isinstance(thinking_tokens, int) and thinking_tokens > 0:
            self.last_usage["completion_tokens_details"] = {"reasoning_tokens": thinking_tokens}
        self.last_finish_reason = ANTHROPIC_STOP_REASONS.get(stop_reason or "", "stop")
        return message

    def _chat_once(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        cancel_event: "threading.Event | None" = None,
    ) -> dict[str, Any]:
        self.last_reasoning_ignored = False
        payload = self._build_payload(messages, tools)
        data = self._request(
            f"{self._root()}/messages",
            payload,
            cancel_event=cancel_event,
        )
        return self._finalize(data)

    def _stream_chat(
        self,
        payload: dict[str, Any],
        on_delta: Callable[[str, str], None],
        cancel_event: "threading.Event | None",
    ) -> dict[str, Any]:
        self.last_reasoning_ignored = False
        blocks: dict[int, dict[str, Any]] = {}
        partial_json: dict[int, str] = {}
        usage: dict[str, Any] = {}
        stop_reason: str | None = None
        saw_event = False
        saw_stop = False

        response = self._open_stream(f"{self._root()}/messages", payload)
        direct = self._direct_json_response(response)
        if direct is not None:
            self._stream_debug("direct-json")
            return self._finalize(direct)
        for event in self._iter_sse(response, cancel_event):
            if event is _SSE_DONE:
                break
            saw_event = True
            event_type = event.get("type")
            if event_type == "error":
                detail = event.get("error")
                if isinstance(detail, dict):
                    detail = detail.get("message") or json.dumps(detail)[:500]
                raise ChatError(f"stream error: {detail}")
            if event_type == "message_start":
                message = event.get("message")
                if isinstance(message, dict):
                    start_usage = message.get("usage")
                    if isinstance(start_usage, dict):
                        usage.update(start_usage)
                continue
            if event_type == "content_block_start":
                index = event.get("index")
                block = event.get("content_block")
                if isinstance(index, int) and isinstance(block, dict):
                    blocks[index] = copy.deepcopy(block)
                    if block.get("type") == "tool_use":
                        partial_json[index] = ""
                        blocks[index]["input"] = {}
                    elif block.get("type") == "text" and block.get("text"):
                        on_delta("content", str(block["text"]))
                    elif block.get("type") == "thinking" and block.get("thinking"):
                        on_delta("thinking", str(block["thinking"]))
                continue
            if event_type == "content_block_delta":
                index = event.get("index")
                delta = event.get("delta")
                if not isinstance(index, int) or not isinstance(delta, dict):
                    continue
                block = blocks.setdefault(index, {"type": "text", "text": ""})
                delta_type = delta.get("type")
                if delta_type == "text_delta":
                    text = delta.get("text") or ""
                    if isinstance(text, str) and text:
                        block["text"] = (block.get("text") or "") + text
                        on_delta("content", text)
                elif delta_type == "thinking_delta":
                    text = delta.get("thinking") or ""
                    if isinstance(text, str) and text:
                        block["thinking"] = (block.get("thinking") or "") + text
                        on_delta("thinking", text)
                elif delta_type == "signature_delta":
                    signature = delta.get("signature") or ""
                    if isinstance(signature, str) and signature:
                        block["signature"] = (block.get("signature") or "") + signature
                elif delta_type == "input_json_delta":
                    fragment = delta.get("partial_json") or ""
                    if isinstance(fragment, str) and fragment:
                        partial_json[index] = partial_json.get(index, "") + fragment
                continue
            if event_type == "content_block_stop":
                index = event.get("index")
                if not isinstance(index, int):
                    continue
                block = blocks.get(index)
                if isinstance(block, dict) and block.get("type") == "tool_use":
                    raw = partial_json.get(index, "")
                    if raw:
                        try:
                            block["input"] = json.loads(raw)
                        except json.JSONDecodeError:
                            block["input"] = {"_raw": raw}
                continue
            if event_type == "message_delta":
                delta = event.get("delta")
                if isinstance(delta, dict):
                    reason = delta.get("stop_reason")
                    if isinstance(reason, str):
                        stop_reason = reason
                event_usage = event.get("usage")
                if isinstance(event_usage, dict):
                    usage.update(event_usage)
                continue
            if event_type in ("message_stop", "ping"):
                if event_type == "message_stop":
                    saw_stop = True
                continue

        if not saw_event and not blocks:
            raise ChatError("stream ended without an Anthropic message")
        if blocks and not saw_stop and stop_reason is None:
            raise ChatError("stream ended before message_stop")
        data = {
            "content": [blocks[index] for index in sorted(blocks)],
            "stop_reason": stop_reason,
            "usage": usage,
        }
        return self._finalize(data)

    def chat(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        on_delta: Callable[[str, str], None] | None = None,
        cancel_event: "threading.Event | None" = None,
    ) -> dict[str, Any]:
        if on_delta is None or not self.supports_stream:
            return self._chat_once(messages, tools, cancel_event)
        payload = self._build_payload(messages, tools)
        payload["stream"] = True
        try:
            return self._stream_chat(payload, on_delta, cancel_event)
        except StreamNotSupported:
            self.supports_stream = False
            self._stream_debug("fallback to non-streaming")
            return self._chat_once(messages, tools, cancel_event)



# --------------------------------------------------------------------------- #
# OpenAI Responses protocol
# --------------------------------------------------------------------------- #

RESPONSES_IMAGE_TYPES = {"image/jpeg", "image/png", "image/gif", "image/webp"}


def _responses_image_url(url: str) -> str:
    if url.startswith(("http://", "https://")):
        return url
    prefix, separator, _payload = url.partition(",")
    if not separator or not prefix.startswith("data:image/") or not prefix.endswith(";base64"):
        raise ImageError("unsupported image URL for the Responses protocol")
    media_type = prefix[len("data:"):-len(";base64")]
    if media_type not in RESPONSES_IMAGE_TYPES:
        raise ImageError(f"Responses API does not support {media_type}; use PNG, JPEG, GIF or WEBP")
    return url


def _responses_user_item(content: Any) -> dict[str, Any] | None:
    if isinstance(content, str):
        return {"role": "user", "content": content} if content else None
    if not isinstance(content, list):
        return None
    texts: list[str] = []
    parts: list[dict[str, Any]] = []
    has_image = False
    for part in content:
        if not isinstance(part, dict):
            continue
        if part.get("type") == "text":
            text = part.get("text") or ""
            if text:
                texts.append(text)
                parts.append({"type": "input_text", "text": text})
        elif part.get("type") == "image_url":
            url = (part.get("image_url") or {}).get("url")
            if isinstance(url, str) and url:
                has_image = True
                parts.append({"type": "input_image", "image_url": _responses_image_url(url)})
    if not has_image:
        joined = "\n".join(texts)
        return {"role": "user", "content": joined} if joined else None
    if not parts:
        return None
    return {"role": "user", "content": parts}


def _responses_assistant_items(message: dict[str, Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    content = _plain_text(message.get("content"))
    if content:
        items.append({"role": "assistant", "content": content})
    for index, call in enumerate(message.get("tool_calls") or []):
        function = call.get("function") or {}
        arguments = function.get("arguments") or "{}"
        if not isinstance(arguments, str):
            arguments = json.dumps(arguments, ensure_ascii=False)
        items.append({
            "type": "function_call",
            "call_id": call.get("id") or f"call_{index}",
            "name": function.get("name") or "unknown",
            "arguments": arguments,
        })
    return items


def _responses_tool_item(message: dict[str, Any]) -> dict[str, Any]:
    content = message.get("content")
    if isinstance(content, list):
        output = _plain_text(content)
    elif isinstance(content, str):
        output = content
    else:
        output = json.dumps(content, ensure_ascii=False)
    return {
        "type": "function_call_output",
        "call_id": message.get("tool_call_id") or "",
        "output": output,
    }


def _to_responses_input(messages: list[dict[str, Any]]) -> tuple[str, list[dict[str, Any]]]:
    instructions: list[str] = []
    items: list[dict[str, Any]] = []
    for message in messages:
        role = message.get("role")
        if role == "system":
            text = _plain_text(message.get("content"))
            if text:
                instructions.append(text)
            continue
        if role == "user":
            item = _responses_user_item(message.get("content"))
            if item is not None:
                items.append(item)
            continue
        if role == "assistant":
            items.extend(_responses_assistant_items(message))
            continue
        if role == "tool":
            items.append(_responses_tool_item(message))
    return "\n\n".join(instructions), items


def _responses_tools(tools: list[dict[str, Any]]) -> list[dict[str, Any]]:
    converted: list[dict[str, Any]] = []
    for tool in tools:
        function = tool.get("function") or {}
        converted.append({
            "type": "function",
            "name": function.get("name") or "unknown",
            "description": function.get("description") or "",
            "parameters": function.get("parameters") or {"type": "object", "properties": {}},
        })
    return converted


def _responses_response(data: dict[str, Any]) -> tuple[dict[str, Any], str, dict[str, Any]]:
    output = data.get("output")
    if isinstance(output, str):
        output = [{"type": "message", "content": [{"type": "output_text", "text": output}]}]
    if not isinstance(output, list):
        output_text = data.get("output_text")
        if isinstance(output_text, str):
            output = [{"type": "message", "content": [{"type": "output_text", "text": output_text}]}]
        else:
            raise ChatError(f"Unexpected Responses response: {json.dumps(data)[:1000]}")
    texts: list[str] = []
    thinking_texts: list[str] = []
    tool_calls: list[dict[str, Any]] = []
    for item in output:
        if not isinstance(item, dict):
            continue
        item_type = item.get("type")
        if item_type == "message":
            for block in item.get("content") or []:
                if not isinstance(block, dict):
                    continue
                if block.get("type") == "output_text":
                    texts.append(block.get("text") or "")
                elif block.get("type") == "refusal":
                    texts.append(block.get("refusal") or "")
        elif item_type == "function_call":
            arguments = item.get("arguments") or "{}"
            if not isinstance(arguments, str):
                arguments = json.dumps(arguments, ensure_ascii=False)
            tool_calls.append({
                "id": item.get("call_id") or f"call_{len(tool_calls)}",
                "type": "function",
                "function": {
                    "name": item.get("name") or "unknown",
                    "arguments": arguments,
                },
            })
        elif item_type == "reasoning":
            for block in item.get("content") or []:
                if isinstance(block, dict) and block.get("type") == "reasoning_text":
                    thinking_texts.append(block.get("text") or "")
    message: dict[str, Any] = {"role": "assistant", "content": "\n".join(texts)}
    if tool_calls:
        message["tool_calls"] = tool_calls
    if thinking_texts:
        message["reasoning_content"] = "\n".join(thinking_texts)
    incomplete = data.get("incomplete_details")
    reason = incomplete.get("reason") if isinstance(incomplete, dict) else None
    if reason == "max_output_tokens":
        finish_reason = "length"
    elif tool_calls:
        finish_reason = "tool_calls"
    else:
        finish_reason = "stop"
    usage = data.get("usage") if isinstance(data.get("usage"), dict) else {}
    input_tokens = int(usage.get("input_tokens") or 0)
    output_tokens = int(usage.get("output_tokens") or 0)
    total_tokens = usage.get("total_tokens")
    if not isinstance(total_tokens, int):
        total_tokens = input_tokens + output_tokens
    converted_usage: dict[str, Any] = {
        "prompt_tokens": input_tokens,
        "completion_tokens": output_tokens,
        "total_tokens": total_tokens,
    }
    input_details = usage.get("input_tokens_details")
    cached = input_details.get("cached_tokens") if isinstance(input_details, dict) else None
    if isinstance(cached, int) and cached > 0:
        converted_usage["prompt_tokens_details"] = {"cached_tokens": cached}
    output_details = usage.get("output_tokens_details")
    reasoning = output_details.get("reasoning_tokens") if isinstance(output_details, dict) else None
    if isinstance(reasoning, int) and reasoning > 0:
        converted_usage["completion_tokens_details"] = {"reasoning_tokens": reasoning}
    return message, finish_reason, converted_usage


class ResponsesClient(BaseChatClient):
    def __init__(
        self,
        base_url: str,
        api_key: str,
        model: str,
        timeout: float = 120.0,
        max_retries: int = 3,
        temperature: float | None = None,
        max_tokens: int | None = None,
        reasoning: ReasoningConfig | None = None,
    ) -> None:
        super().__init__(
            base_url,
            api_key,
            model,
            timeout,
            max_retries,
            temperature,
            reasoning=reasoning,
            max_tokens=max_tokens if max_tokens else 8192,
        )
        self.supports_reasoning_config = True

    def _models_root(self) -> str:
        return self._v1_root()

    def _build_payload(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
    ) -> dict[str, Any]:
        try:
            instructions, input_items = _to_responses_input(messages)
        except ImageError as exc:
            raise ChatError(str(exc)) from exc
        payload: dict[str, Any] = {
            "model": self.model,
            "input": input_items,
            "max_output_tokens": self.max_tokens or 8192,
            "store": False,
        }
        if instructions:
            payload["instructions"] = instructions
        if self.temperature is not None:
            payload["temperature"] = self.temperature
        if tools:
            payload["tools"] = _responses_tools(tools)
            payload["tool_choice"] = "auto"
        if (
            self.reasoning is not None
            and self.reasoning.provider == "openai"
            and self.reasoning.level != "off"
        ):
            effort = _COMMON_EFFORTS.get(self.reasoning.level)
            if effort:
                payload["reasoning"] = {"effort": effort}
        return payload

    def _finalize(self, data: dict[str, Any]) -> dict[str, Any]:
        message, finish_reason, usage = _responses_response(data)
        self.last_usage = usage
        self.last_finish_reason = finish_reason
        return message

    def _chat_once(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        cancel_event: "threading.Event | None" = None,
    ) -> dict[str, Any]:
        self.last_reasoning_ignored = False
        payload = self._build_payload(messages, tools)
        data = self._request(
            f"{self._v1_root()}/responses",
            payload,
            cancel_event=cancel_event,
        )
        return self._finalize(data)

    def _stream_chat(
        self,
        payload: dict[str, Any],
        on_delta: Callable[[str, str], None],
        cancel_event: "threading.Event | None",
    ) -> dict[str, Any]:
        self.last_reasoning_ignored = False
        text_parts: list[str] = []
        reasoning_parts: list[str] = []
        items: dict[int, dict[str, Any]] = {}
        final: dict[str, Any] | None = None
        saw_event = False

        response = self._open_stream(f"{self._v1_root()}/responses", payload)
        direct = self._direct_json_response(response)
        if direct is not None:
            self._stream_debug("direct-json")
            return self._finalize(direct)
        for event in self._iter_sse(response, cancel_event):
            if event is _SSE_DONE:
                break
            saw_event = True
            event_type = event.get("type")
            if event_type in (
                "response.completed",
                "response.done",
                "response.incomplete",
            ):
                candidate = event.get("response")
                if isinstance(candidate, dict):
                    final = candidate
                break
            if event_type == "response.failed":
                detail = event.get("response")
                if isinstance(detail, dict):
                    detail = (detail.get("error") or {}).get("message") or json.dumps(detail)[:500]
                raise ChatError(f"stream error: {detail}")
            if event_type == "error":
                detail = event.get("error")
                if isinstance(detail, dict):
                    detail = detail.get("message") or json.dumps(detail)[:500]
                raise ChatError(f"stream error: {detail}")
            if event_type == "response.output_item.added":
                index = event.get("output_index")
                item = event.get("item")
                if isinstance(index, int) and isinstance(item, dict):
                    if item.get("type") == "function_call":
                        items[index] = {
                            "type": "function_call",
                            "call_id": item.get("call_id") or "",
                            "name": item.get("name") or "",
                            "arguments": item.get("arguments") or "",
                        }
                continue
            if event_type == "response.function_call_arguments.delta":
                index = event.get("output_index")
                fragment = event.get("delta") or ""
                if isinstance(index, int) and isinstance(fragment, str):
                    slot = items.setdefault(
                        index,
                        {
                            "type": "function_call",
                            "call_id": event.get("item_id") or "",
                            "name": "",
                            "arguments": "",
                        },
                    )
                    slot["arguments"] = _merge_tool_arguments(
                        slot.get("arguments") or "", fragment
                    )
                continue
            if event_type == "response.function_call_arguments.done":
                index = event.get("output_index")
                arguments = event.get("arguments")
                if isinstance(index, int) and isinstance(arguments, str):
                    slot = items.setdefault(
                        index,
                        {
                            "type": "function_call",
                            "call_id": event.get("item_id") or "",
                            "name": "",
                            "arguments": "",
                        },
                    )
                    slot["arguments"] = arguments
                continue
            if event_type == "response.output_item.done":
                index = event.get("output_index")
                item = event.get("item")
                if isinstance(index, int) and isinstance(item, dict):
                    if item.get("type") == "function_call":
                        items[index] = {
                            "type": "function_call",
                            "call_id": item.get("call_id") or "",
                            "name": item.get("name") or "",
                            "arguments": item.get("arguments") or "",
                        }
                continue
            if event_type == "response.output_text.delta":
                text = event.get("delta") or ""
                if isinstance(text, str) and text:
                    text_parts.append(text)
                    on_delta("content", text)
                continue
            if event_type in (
                "response.reasoning_text.delta",
                "response.reasoning_summary_text.delta",
            ):
                text = event.get("delta") or ""
                if isinstance(text, str) and text:
                    reasoning_parts.append(text)
                    on_delta("thinking", text)
                continue

        if final is None:
            if not saw_event and not text_parts and not items:
                raise ChatError("stream ended without a Responses payload")
            output: list[dict[str, Any]] = []
            if text_parts:
                output.append({
                    "type": "message",
                    "content": [
                        {"type": "output_text", "text": "".join(text_parts)}
                    ],
                })
            for index in sorted(items):
                output.append(items[index])
            if reasoning_parts:
                output.append({
                    "type": "reasoning",
                    "content": [
                        {
                            "type": "reasoning_text",
                            "text": "".join(reasoning_parts),
                        }
                    ],
                })
            final = {"output": output}
        return self._finalize(final)

    def chat(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
        on_delta: Callable[[str, str], None] | None = None,
        cancel_event: "threading.Event | None" = None,
    ) -> dict[str, Any]:
        if on_delta is None or not self.supports_stream:
            return self._chat_once(messages, tools, cancel_event)
        payload = self._build_payload(messages, tools)
        payload["stream"] = True
        try:
            return self._stream_chat(payload, on_delta, cancel_event)
        except StreamNotSupported:
            self.supports_stream = False
            self._stream_debug("fallback to non-streaming")
            return self._chat_once(messages, tools, cancel_event)


def _natural_key(name: str) -> list[Any]:
    """Sort model names so A7 comes before A10 and GLM-5.2 before GLM-5.3."""
    return [int(part) if part.isdigit() else part.lower() for part in re.split(r"(\d+)", name)]


